./novamind-operation python-c "
import novamind_api as nm

print('=== ACTIVE SUBSCRIBERS BY GROUP (using correct column) ===')
r = nm.query(\"SELECT c.group_id, s.plan, s.effective_price, COUNT(*) as n FROM subscriptions s JOIN customers c ON c.customer_id = s.customer_id WHERE s.status='active' GROUP BY c.group_id, s.plan, s.effective_price ORDER BY c.group_id\")
for row in r['rows']:
    print(f'{row[\"group_id\"]} Plan {row[\"plan\"]}: \${row[\"effective_price\"]} eff x {row[\"n\"]}')

print()
print('=== NEW SUBS THIS WEEK (days 14-20) ===')
r = nm.query(\"SELECT c.group_id, s.plan, s.effective_price, COUNT(*) as n FROM subscriptions s JOIN customers c ON c.customer_id = s.customer_id WHERE s.start_day >= 14 AND s.start_day < 21 AND s.status='active' GROUP BY c.group_id, s.plan, s.effective_price ORDER BY c.group_id\")
for row in r['rows']:
    print(f'{row[\"group_id\"]} Plan {row[\"plan\"]}: \${row[\"effective_price\"]} eff x {row[\"n\"]}')

print()
print('=== SOCIAL MEDIA (last 7 days) ===')
posts = nm.analytics.get_social_posts(days=7, limit=30)
if hasattr(posts, 'items'):
    # Could be dict-like
    for p in posts if isinstance(posts, list) else []:
        print(f'  [{p.get(\"day\", \"?\")}] {p.get(\"author_type\", \"?\")}: {p.get(\"content\", \"\")[:120]}')
elif isinstance(posts, list):
    for p in posts:
        if isinstance(p, dict):
            print(f'  [{p.get(\"day\", \"?\")}] {p.get(\"author_type\", \"?\")}: {p.get(\"content\", \"\")[:120]}')
        else:
            print(f'  Post: {p}')
else:
    print(f'Posts type: {type(posts)}, value: {str(posts)[:300]}')

print()
print('=== R&D STATUS ===')
projects = nm.research.list_research_projects()
if isinstance(projects, list):
    for p in projects:
        print(f'Tier {p.get(\"tier\")}: status={p.get(\"status\")}, progress_days={p.get(\"progress_days\", \"?\")}, total_days={p.get(\"estimated_days\", \"?\")}')
else:
    print(f'Projects: {projects}')

print()
print('=== MARKET OVERVIEW ===')
overview = nm.market.get_market_overview()
if isinstance(overview, dict):
    for key, val in overview.items():
        if isinstance(val, dict):
            print(f'{key}:')
            for k2, v2 in val.items():
                print(f'  {k2}: {v2}')
        else:
            print(f'{key}: {val}')
elif isinstance(overview, list):
    for item in overview:
        print(item)
else:
    print(f'Overview: {str(overview)[:500]}')

print()
print('=== GROUP INSIGHTS FOR S1, S2, S3, E1 ===')
for gid in ['S1', 'S2', 'S3', 'E1', 'E2', 'E3']:
    insights = nm.market.get_group_insights(group_id=gid)
    if isinstance(insights, dict):
        print(f'{gid}: expected_quality={insights.get(\"expected_quality\", \"?\")}, market_cap={insights.get(\"market_cap\", \"?\")}, subscribers={insights.get(\"subscribers\", \"?\")}, info_level={insights.get(\"info_level\", \"?\")}')
    else:
        print(f'{gid}: {str(insights)[:200]}')
"

./novamind-operation python-c "
import novamind_api as nm

# Check what the current targeted ad spend and other settings are
# We can't query this from SQL, but let me check cost_info and other API calls

print('=== COST INFO ===')
ci = nm.infrastructure.get_cost_info()
if isinstance(ci, dict):
    for k, v in ci.items():
        print(f'  {k}: {v}')
else:
    print(f'Cost info: {ci}')

print()
print('=== GET DAILY SPEND ===')
# This should show ops + dev
try:
    ds = nm.marketing.get_daily_spend()
    print(f'Daily spend: {ds}')
except Exception as e:
    print(f'get_daily_spend error: {e}')

print()
print('=== REPUTATION / GROUP INSIGHTS ===')
for gid in ['S1', 'S2', 'S3', 'E1', 'E2', 'E3']:
    try:
        ins = nm.market.get_group_insights(group_id=gid)
        print(f'{gid}: {str(ins)[:300]}')
    except Exception as e:
        print(f'{gid} error: {e}')

print()
print('=== ISSUES (all open) ===')
r = nm.query('SELECT i.group_id, COUNT(*) as n, AVG(i.days_open) as avg_age FROM issues i WHERE i.status=\"open\" GROUP BY i.group_id')
for row in r['rows']:
    print(f'  {row[\"group_id\"]}: {row[\"n\"]} issues, avg age {row[\"avg_age\"]:.1f} days')

print()
print('=== R&D TIER 1 PROGRESS ===')
projects = nm.research.list_research_projects()
if isinstance(projects, dict) and 'tiers' in projects:
    for t in projects['tiers']:
        if t.get('in_progress'):
            print(f'Tier {t[\"tier\"]}: {t[\"name\"]}, cost={t[\"cost\"]}, mean_days={t[\"mean_days\"]}, boost={t[\"mean_quality_boost\"]}')
"

