./novamind-operation python-c "
import novamind_api as nm

print('=== Group Insights: S1, S2, S3 ===')
for g in ['S1', 'S2', 'S3']:
    print(f'\\n--- {g} ---')
    insights = nm.market.get_group_insights(group_id=g)
    for k,v in insights.items():
        if isinstance(v, dict):
            print(f'  {k}:')
            for k2,v2 in v.items():
                print(f'    {k2}: {v2}')
        elif isinstance(v, list):
            print(f'  {k}: {v}')
        else:
            print(f'  {k}: {v}')

print('\\n=== Social posts this week ===')
posts = nm.analytics.get_social_posts(days=7, limit=30)
for p in posts:
    print(f\"Day {p.get('day','?')} | Grp {p.get('group_id','?')} | {p.get('content','')[:200]}\")

print('\\n=== Research projects table ===')
r = nm.query('SELECT * FROM research_projects')
for row in r['rows']:
    print(row)

print('\\n=== List Research (API) ===')
try:
    projects = nm.research.list_research_projects()
    print(type(projects))
    print(projects)
except Exception as e:
    print(f'Error: {e}')
"

