./novamind-operation python-c "
import novamind_api as nm

# R&D status
projects = nm.research.list_research_projects()
print('=== R&D Projects ===')
print(type(projects))
if isinstance(projects, list):
    for p in projects:
        print(f'Item type: {type(p)}, value: {p}')
elif isinstance(projects, dict):
    for k, v in projects.items():
        print(f'{k}: {v}')
else:
    print(projects)

# Social posts
posts = nm.analytics.get_social_posts(days=7, limit=30)
print('\n=== Social Posts ===')
if posts:
    for p in posts:
        print(f'  [{p.get(\"date\", \"?\")}] grp={p.get(\"group_id\", \"?\")}: {p.get(\"content\", \"\")[:150]}')

# Cash flow - try again
try:
    result = nm.query('SELECT SUM(amount) as total FROM ledger WHERE date >= 70 AND date < 77')
    if result and result['rows']:
        total = result['rows'][0]['total']
        print(f'Cash flow days 70-76: \${total:.0f}')
except Exception as e:
    print(f'Cash flow error: {e}')

# Revenue vs expenses 
try:
    result_rev = nm.query('SELECT SUM(amount) as rev FROM ledger WHERE date >= 70 AND date < 77 AND amount > 0')
    if result_rev and result_rev['rows']:
        rev = result_rev['rows'][0]['rev']
        print(f'Revenue (positive): \${rev:.0f}')

    result_exp = nm.query('SELECT SUM(amount) as exp FROM ledger WHERE date >= 70 AND date < 77 AND amount < 0')
    if result_exp and result_exp['rows']:
        exp = result_exp['rows'][0]['exp']
        print(f'Expenses (negative): \${exp:.0f}')
except Exception as e:
    print(f'Error: {e}')
"

